const eventosOcupados = $input.all().map(item => ({
  inicio: new Date(item.json.start.dateTime),
  fin: new Date(item.json.end.dateTime)
}));

const disponibilidad = {};
const hoyArgentina = $now.setZone('America/Argentina/Tucuman');

for (let i = 0; i < 7; i++) {
  if (i === 0) {
    continue;
  }

  let fechaActual = hoyArgentina.plus({ days: i }).set({ hour: 12, minute: 0, second: 0, millisecond: 0 });
  const numeroDiaSemana = fechaActual.weekday; 

  if (numeroDiaSemana === 6 || numeroDiaSemana === 7) {
    continue; 
  }

  let diaLegible = fechaActual.setLocale('es-ES').toFormat('cccc d \'de\' MMMM');
  diaLegible = diaLegible.charAt(0).toUpperCase() + diaLegible.slice(1);

  const slotsDelDia = [];

  for (let hora = 13; hora < 18; hora++) {
    const slotInicioLuxon = fechaActual.set({ hour: hora, minute: 0, second: 0, millisecond: 0 });
    const slotFinLuxon = slotInicioLuxon.plus({ hours: 1 });

    const slotInicio = new Date(slotInicioLuxon.toISO());
    const slotFin = new Date(slotFinLuxon.toISO());

    const conflicto = eventosOcupados.some(evento => {
      return (slotInicio < evento.fin && slotFin > evento.inicio);
    });

    if (!conflicto) {
      const horaLegible = slotInicioLuxon.toFormat('h:mm a');
      slotsDelDia.push(horaLegible);
    }
  }

  if (slotsDelDia.length > 0) {
    disponibilidad[diaLegible] = slotsDelDia;
  }
}

return [{ json: { turnosLibres: disponibilidad } }];
